<div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4"><div><h1>My Garden</h1><p class="text-muted mb-0">Independent records of what you actually planted. Actual dates always take precedence over estimates.</p></div><a class="btn btn-success" href="<?=e(url('garden/create'))?>">Add Planting</a></div>
<?php foreach($groups as $heading=>$plantings):?>
<section class="mb-4" aria-labelledby="garden-<?=e(strtolower(str_replace(' ','-',$heading)))?>"><h2 id="garden-<?=e(strtolower(str_replace(' ','-',$heading)))?>" class="h4"><?=e($heading)?> <span class="badge text-bg-secondary"><?=count($plantings)?></span></h2>
<?php if(!$plantings):?><div class="card card-body text-muted">No plantings in this section.</div><?php else:?><div class="row g-3"><?php foreach($plantings as $p):?><div class="col-12 col-xl-6"><article class="card h-100"><div class="card-body"><div class="d-flex justify-content-between gap-2"><h3 class="h5"><a href="<?=e(url('garden/'.$p['id']))?>"><?=e($p['seed_name'])?><?=($p['variety']??'')!==''?' — '.e($p['variety']):''?></a></h3><span class="badge text-bg-light"><?=e($p['status'])?></span></div><p class="mb-2"><strong>Actual planted:</strong> <?=e($p['planted_date'])?> · <?=e($p['planting_method'])?> · Qty <?=e($p['quantity'])?><br><strong>Location:</strong> <?=e($p['location'])?></p>
<?php foreach(['_germination'=>'Expected germination','_transplant'=>'Expected transplant','_harvest'=>'Expected harvest'] as $key=>$label):?><div class="small"><strong><?=e($label)?>:</strong> <?php if($p[$key]):?><?=e($p[$key][0])?><?= $p[$key][1]!==$p[$key][0]?' – '.e($p[$key][1]):''?> <span class="text-muted">(calculated)</span><?php else:?><span class="text-muted">Unavailable — not enough supported data<?=(($key==='_transplant'&&!empty($p['actual_transplant_date']))||($key==='_harvest'&&!empty($p['actual_harvest_date'])))?' or actual date recorded':''?>.</span><?php endif?></div><?php endforeach?>
<?php if(!empty($p['actual_transplant_date'])):?><div><strong>Actual transplant:</strong> <?=e($p['actual_transplant_date'])?></div><?php endif?><?php if(!empty($p['actual_harvest_date'])):?><div><strong>Actual harvest:</strong> <?=e($p['actual_harvest_date'])?></div><?php endif?>
<div class="d-flex flex-wrap gap-2 mt-3"><a class="btn btn-sm btn-outline-success" href="<?=e(url('garden/'.$p['id']))?>">View / Edit</a><?php if(!in_array($p['status'],['Archived','Harvested','Failed'],true)):?><form method="post" action="<?=e(url('garden/'.$p['id'].'/status'))?>"><?=csrf_field()?><input type="hidden" name="status" value="Archived"><button class="btn btn-sm btn-outline-secondary">Archive</button></form><?php endif?></div></div></article></div><?php endforeach?></div><?php endif?></section>
<?php endforeach?>
